def test_iterate_walks_pages_until_total(client, httpx_mock):
    first = [record(RECORD_ID)]
    second = [record(5534443, conceptrecid=CONCEPT_ID)]
    httpx_mock.add_response(json=envelope(first, total=2))
    httpx_mock.add_response(json=envelope(second, total=2))
    pages = []
    records = [
        item
        for item in client.records.iterate(
            query="communities:ror-data", on_page=lambda n, _: pages.append(n)
        )
    ]
    assert [item.id for item in records] == [RECORD_ID, 5534443]
    assert pages == [1, 2]
    assert last_params(httpx_mock)["page"] == "2"


